import React, { useState, useEffect } from 'react';
import { ethers } from 'ethers';
import Empresas from './components/Empresas';
import Clientes from './components/Clientes';

const CONTRACT_ADDRESS = '0x73Ae10E84468c30e564A02d6e18068D10854A333';

function App() {
  const [provider, setProvider] = useState(null);
  const [account, setAccount] = useState('');
  const [activeTab, setActiveTab] = useState('empresas');
  const [loading, setLoading] = useState(false);
  const [status, setStatus] = useState({ type: '', message: '' });

  // Conectar a MetaMask
  const connectWallet = async () => {
    try {
      if (typeof window.ethereum !== 'undefined') {
        const accounts = await window.ethereum.request({
          method: 'eth_requestAccounts'
        });
        
        const provider = new ethers.BrowserProvider(window.ethereum);
        const signer = await provider.getSigner();
        const contract = new ethers.Contract(CONTRACT_ADDRESS, ABI_EMPRESA, signer);
        
        setProvider(provider);
        setAccount(accounts[0]);
        
        setStatus({
          type: 'success',
          message: 'Wallet conectada exitosamente!'
        });
      } else {
        setStatus({
          type: 'error',
          message: 'Por favor instala MetaMask para usar esta aplicación'
        });
      }
    } catch (error) {
      console.error('Error conectando wallet:', error);
      setStatus({
        type: 'error',
        message: 'Error conectando wallet: ' + error.message
      });
    }
  };



  // Escuchar cambios en la cuenta
  useEffect(() => {
    if (typeof window.ethereum !== 'undefined') {
      window.ethereum.on('accountsChanged', (accounts) => {
        if (accounts.length > 0) {
          setAccount(accounts[0]);
        } else {
          setAccount('');
          setProvider(null);
        }
      });

      window.ethereum.on('chainChanged', () => {
        window.location.reload();
      });
    }
  }, []);

  return (
    <div className="container">
      <div className="header">
        <h1>🏢 Gestión de Empresas</h1>
        <p>Gestiona empresas en la blockchain de Ethereum</p>
      </div>

      {!account ? (
        <div className="card">
          <h2>Conectar Wallet</h2>
          <p>Para usar esta aplicación, necesitas conectar tu wallet de MetaMask.</p>
          <button className="btn" onClick={connectWallet}>
            🔗 Conectar MetaMask
          </button>
        </div>
      ) : (
        <>
          <div className="wallet-info">
            <h3>Wallet Conectada</h3>
            <p><strong>Dirección:</strong> {account}</p>
            <p><strong>Red:</strong> {provider?.network?.name || 'Conectando...'}</p>
          </div>

          <div className="card">
            <h2>➕ Agregar Nueva Empresa</h2>
            <form onSubmit={agregarEmpresa}>
              <div className="form-group">
                <label htmlFor="empresaNombre">Nombre de la Empresa:</label>
                <input
                  type="text"
                  id="empresaNombre"
                  value={empresaNombre}
                  onChange={(e) => setEmpresaNombre(e.target.value)}
                  placeholder="Ingresa el nombre de la empresa"
                  disabled={loading}
                />
              </div>
              <button 
                type="submit" 
                className="btn" 
                disabled={loading || !empresaNombre.trim()}
              >
                {loading ? 'Procesando...' : 'Agregar Empresa'}
              </button>
            </form>
          </div>

          <div className="card">
            <h2>📋 Lista de Empresas</h2>
            <button 
              className="btn btn-secondary" 
              onClick={cargarEmpresas}
              disabled={loading}
              style={{ marginBottom: '20px' }}
            >
              🔄 Actualizar Lista
            </button>
            
            {loading ? (
              <div className="loading">Cargando empresas...</div>
            ) : empresas.length === 0 ? (
              <p>No hay empresas registradas aún.</p>
            ) : (
              <div className="empresas-grid">
                {empresas.map((empresa, index) => (
                  <div key={index} className="empresa-item">
                    <h3>{empresa.nombre}</h3>
                    <p><strong>Dirección:</strong> {empresa.direccion}</p>
                  </div>
                ))}
              </div>
            )}
          </div>
        </>
      )}

      {status.message && (
        <div className={`status ${status.type}`}>
          {status.message}
        </div>
      )}
    </div>
  );
}

export default App;
